#!/usr/bin/env python3
"""Generate wire.cir: Example 24-06.1's 2 mm interposer wire as a 40-section RC ladder.

Driver: an ideal 0.5 V step (0.1 ps edge) through Ron = 50 ohm. Wire: Rw = 50 ohm, Cw = 200 fF in
40 sections (half-capacitors at the ends). Pads: 50 fF at each end.
"""
from pathlib import Path

N, RW, CW, CPAD = 40, 50.0, 200e-15, 50e-15
lines = [
    "* 24-06 lab: energy and speed of a 2 mm unterminated interposer wire (Example 24-06.1)",
    "* 40-section RC ladder, Rw = 50 ohm, Cw = 200 fF, 50 fF pads at each end, 50 ohm driver, 0.5 V step.",
    "* Generated by make_wire.py.",
    "* EXPECT esrc key:../../chapters/24-06-d2d-memory-phys-scale-up.md#Ex_24-06.1a scale=1e-15 rtol=0.002",
    "* EXPECT trise key:../../chapters/24-06-d2d-memory-phys-scale-up.md#Txt_24-06.a scale=1e-12 rtol=0.005",
    "* EXPECT tdel key:../../chapters/24-06-d2d-memory-phys-scale-up.md#Txt_24-06.b scale=1e-12 rtol=0.01",
    "V1 in 0 PWL(0 0 10p 0 10.1p 0.5)",
    "Ron in n0 50",
]
for i in range(N):
    lines.append(f"R{i} n{i} n{i+1} {RW / N:.6g}")
for i in range(N + 1):
    c = CW / N if 0 < i < N else CW / N / 2 + CPAD
    lines.append(f"C{i} n{i} 0 {c:.6g}")
lines += [
    ".control",
    "tran 0.02p 1n 0 0.02p",
    "let p = -v(in)*i(v1)",
    "meas tran esrc integ p from=0 to=1n",
    "meas tran t10 when v(n40)=0.05 rise=1",
    "meas tran t90 when v(n40)=0.45 rise=1",
    "let trise = t90 - t10",
    "print trise",
    "meas tran tdel trig v(in) val=0.25 rise=1 targ v(n40) val=0.25 rise=1",
    ".endc",
    ".end",
]
Path(__file__).with_name("wire.cir").write_text("\n".join(lines) + "\n")
